package gr.myworkstation.chat;
import android.app.AlertDialog;import android.content.Context;import android.graphics.Bitmap;import android.graphics.RectF;import android.os.SystemClock;import android.view.MotionEvent;import android.view.View;import android.view.ViewGroup;import android.view.WindowManager;import android.widget.LinearLayout;
import androidx.test.platform.app.InstrumentationRegistry;import androidx.lifecycle.Lifecycle;import androidx.test.core.app.ActivityScenario;import androidx.test.core.app.ApplicationProvider;import androidx.test.ext.junit.runners.AndroidJUnit4;import java.lang.reflect.Field;import java.lang.reflect.Method;import org.json.JSONArray;import org.json.JSONObject;import org.junit.Before;import org.junit.After;import org.junit.Test;import org.junit.runner.RunWith;import static org.junit.Assert.*;
/** Actual native views, gestures and lifecycle; RAM-only synthetic fixture, never production. */
@RunWith(AndroidJUnit4.class) public class ChatFamiliarUiActivityTest {
 @Before public void clear(){Context c=ApplicationProvider.getApplicationContext();new TokenVault(c).clear();TokenVault.pendingTwoFactor(c).clear();}
 @After public void clean(){clear();}
 private Object get(MainActivity a,String n)throws Exception{Field f=MainActivity.class.getDeclaredField(n);f.setAccessible(true);return f.get(a);}
 private void set(MainActivity a,String n,Object v)throws Exception{Field f=MainActivity.class.getDeclaredField(n);f.setAccessible(true);f.set(a,v);}
 private void call(MainActivity a,String n)throws Exception{Method m=MainActivity.class.getDeclaredMethod(n);m.setAccessible(true);m.invoke(a);}
 private ZoomPhotoView photo(View v){if(v instanceof ZoomPhotoView)return (ZoomPhotoView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){ZoomPhotoView z=photo(((ViewGroup)v).getChildAt(i));if(z!=null)return z;}return null;}
 private void tap(ZoomPhotoView v,long down,long time,int action,float x,float y){MotionEvent e=MotionEvent.obtain(down,time,action,x,y,0);v.dispatchTouchEvent(e);e.recycle();}
 private void pinch(ZoomPhotoView v,long time,int action,float x1,float x2){MotionEvent.PointerProperties[] p={new MotionEvent.PointerProperties(),new MotionEvent.PointerProperties()};MotionEvent.PointerCoords[] c={new MotionEvent.PointerCoords(),new MotionEvent.PointerCoords()};for(int i=0;i<2;i++){p[i].id=i;p[i].toolType=MotionEvent.TOOL_TYPE_FINGER;c[i].x=i==0?x1:x2;c[i].y=250;c[i].pressure=1;c[i].size=1;}MotionEvent e=MotionEvent.obtain(time,time,action,2,p,c,0,0,1,1,0,0,0,0);v.dispatchTouchEvent(e);e.recycle();}
 @Test public void actualPhotoFitsPortraitAndLandscapeAndDoubleTapPinchPanResetAreBounded()throws Exception{
  try(ActivityScenario<MainActivity>s=ActivityScenario.launch(MainActivity.class)){s.onActivity(a->{Bitmap bitmap=Bitmap.createBitmap(1200,600,Bitmap.Config.ARGB_8888);try{ZoomPhotoView v=new ZoomPhotoView(a);v.setImageBitmap(bitmap);a.setContentView(v);v.layout(0,0,300,500);v.resetZoom();RectF r=v.displayedBounds();assertEquals(300,r.width(),.01);assertEquals(150,r.height(),.01);assertEquals(175,r.top,.01);
   long t=SystemClock.uptimeMillis();tap(v,t,t,MotionEvent.ACTION_DOWN,150,250);tap(v,t,t+40,MotionEvent.ACTION_UP,150,250);tap(v,t+100,t+100,MotionEvent.ACTION_DOWN,150,250);tap(v,t+100,t+140,MotionEvent.ACTION_UP,150,250);assertTrue(v.displayedBounds().width()>300);v.resetZoom();
   tap(v,t+500,t+500,MotionEvent.ACTION_DOWN,110,250);pinch(v,t+520,MotionEvent.ACTION_POINTER_DOWN|(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT),110,190);pinch(v,t+550,MotionEvent.ACTION_MOVE,30,270);pinch(v,t+580,MotionEvent.ACTION_MOVE,0,300);assertTrue("Real pinch must zoom",v.displayedBounds().width()>300);tap(v,t+500,t+600,MotionEvent.ACTION_UP,0,250);
   tap(v,t+1000,t+1000,MotionEvent.ACTION_DOWN,150,250);tap(v,t+1000,t+1050,MotionEvent.ACTION_MOVE,10000,10000);tap(v,t+1000,t+1100,MotionEvent.ACTION_UP,10000,10000);r=v.displayedBounds();assertTrue(r.left<=.01&&r.right>=299.99);if(r.height()>500)assertTrue(r.top<=.01&&r.bottom>=499.99);v.resetZoom();assertEquals(300,v.displayedBounds().width(),.01);
   v.layout(0,0,500,300);v.resetZoom();assertEquals(500,v.displayedBounds().width(),.01);assertEquals(250,v.displayedBounds().height(),.01);
  }finally{ZoomPhotoView old=photo(a.getWindow().getDecorView());if(old!=null)old.setImageDrawable(null);a.setContentView(new LinearLayout(a));bitmap.recycle();}});}
 }
 @Test public void fullPhotoIsSecureFillsWindowAndBackgroundRecyclesPrivateBitmap()throws Exception{
  final Bitmap[] bitmap={null};final AlertDialog[] dialog={null};try(ActivityScenario<MainActivity>s=ActivityScenario.launch(MainActivity.class)){s.onActivity(a->{try{bitmap[0]=Bitmap.createBitmap(600,1200,Bitmap.Config.ARGB_8888);set(a,"preview",bitmap[0]);Method m=MainActivity.class.getDeclaredMethod("showFullPhoto",String.class,Bitmap.class);m.setAccessible(true);m.invoke(a,"Synthetic",bitmap[0]);dialog[0]=(AlertDialog)get(a,"imageDialog");assertTrue(dialog[0].isShowing());assertTrue((dialog[0].getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_SECURE)!=0);assertEquals(-1,dialog[0].getWindow().getAttributes().height);assertNotNull(photo(dialog[0].getWindow().getDecorView()));}catch(Exception e){throw new AssertionError(e);}});InstrumentationRegistry.getInstrumentation().waitForIdleSync();s.onActivity(a->{ZoomPhotoView view=photo(dialog[0].getWindow().getDecorView());assertTrue("Photo surface must have real full-window height",view.getHeight()>200);assertTrue(view.getWidth()>200);RectF r=view.displayedBounds();assertTrue(r.left>=-1&&r.top>=-1&&r.right<=view.getWidth()+1&&r.bottom<=view.getHeight()+1);});s.moveToState(Lifecycle.State.CREATED);assertFalse(dialog[0].isShowing());assertTrue(bitmap[0].isRecycled());}
 }
 @Test public void actualLongPressShowsActionsWithoutAnyReadOrSendAndClosesOnStoreNavigation()throws Exception{
  final int[] writes={0};try(ActivityScenario<MainActivity>s=ActivityScenario.launch(MainActivity.class)){s.onActivity(a->{try{JSONObject store=new JSONObject().put("id","familiar-fixture").put("companyId","fixture-company").put("name","Synthetic");set(a,"selected",store);set(a,"token","fixture-token");set(a,"identity",new JSONObject().put("id","actor").put("role","OWNER"));set(a,"api",new ChatApi(){@Override JSONObject json(String p,String method,JSONObject b,String t)throws Exception{if(!method.equals("GET")){writes[0]++;throw new AssertionError("No implicit mutation");}return new JSONObject().put("store",store).put("rows",new JSONArray().put(new JSONObject().put("id","fixture-message").put("body","Synthetic message").put("readByMe",true).put("deliveredByMe",true))).put("interactionsAvailable",true).put("settings",new JSONObject());}});call(a,"conversation");}catch(Exception e){throw new AssertionError(e);}});
   boolean ready=false;for(int i=0;i<100;i++){boolean[] idle={false};s.onActivity(a->{try{idle[0]=!(Boolean)get(a,"busy");}catch(Exception e){throw new AssertionError(e);}});if(idle[0]){ready=true;break;}Thread.sleep(30);}assertTrue(ready);
   s.onActivity(a->{try{LinearLayout messages=(LinearLayout)get(a,"messages"),card=(LinearLayout)messages.getChildAt(0);View actions=card.findViewWithTag("message-actions");assertEquals(View.GONE,actions.getVisibility());assertTrue(card.performLongClick());AlertDialog d=(AlertDialog)get(a,"imageDialog");assertTrue(d.isShowing());assertEquals(View.GONE,actions.getVisibility());View actual=d.getWindow().getDecorView().findViewWithTag("message-actions");assertTrue(actual.isShown());assertTrue((d.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_SECURE)!=0);call(a,"navigate");assertFalse(d.isShowing());assertEquals(View.GONE,actions.getVisibility());assertEquals("",((android.widget.TextView)((LinearLayout)actual).getChildAt(0)).getText().toString());}catch(Exception e){throw new AssertionError(e);}});assertEquals(0,writes[0]);}
 }
}
